const triplesSumToZero = (l) => {
  if (!l || l.length < 3) {
    return false;
  }
  const sorted = [...l].sort((a, b) => a - b);
  const n = sorted.length;
  for (let i = 0; i < n - 2; i++) {
    if (i > 0 && sorted[i] === sorted[i - 1]) {
      continue;
    }
    let left = i + 1;
    let right = n - 1;
    while (left < right) {
      const sum = sorted[i] + sorted[left] + sorted[right];
      if (sum === 0) {
        return true;
      } else if (sum < 0) {
        left++;
      } else {
        right--;
      }
    }
  }
  return false;
};

